import{_ as e,o as r,c as o,a4 as s}from"./chunks/framework.bruR1JhL.js";const c=JSON.parse('{"title":"Printing","description":"Print PDFs with control over paper, two-sided printing, pages per sheet, booklets, crop marks and scaling.","frontmatter":{"title":"Printing","description":"Print PDFs with control over paper, two-sided printing, pages per sheet, booklets, crop marks and scaling."},"headers":[],"relativePath":"docs/print.md","filePath":"docs/print.md","lastUpdated":1795509372000}'),n={name:"docs/print.md"};function a(i,t,d,h,l,g){return r(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="printing" tabindex="-1">Printing <a class="header-anchor" href="#printing" aria-label="Permalink to &quot;Printing&quot;">​</a></h1><p>The Printing category has one tool, Advanced Print. It prints a PDF with more control than a normal print dialog, and shows the sheets exactly as they will come out of the printer.</p><p>Open a PDF with <strong>Open PDF…</strong>, with <strong>Use</strong> followed by the selected file&#39;s name, or by dragging it from the Explorer. You can also right-click a PDF in the Explorer and choose <strong>Print…</strong>. See <a href="/tilepress/docs/interface">The Tilepress window</a> for the Explorer and the other general controls.</p><h2 id="advanced-print" tabindex="-1">Advanced Print <a class="header-anchor" href="#advanced-print" aria-label="Permalink to &quot;Advanced Print&quot;">​</a></h2><p>Prints a PDF on any installed printer, with two-sided printing, several pages per sheet, booklets, crop marks and scaling. <strong>Save layout as PDF…</strong> writes the arranged sheets to a new PDF instead of printing them.</p><h3 id="how-to-use-it" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>Open a PDF.</li><li>Choose the <strong>Printer</strong>, the number of <strong>Copies</strong>, <strong>Two-sided</strong> and <strong>Colour</strong>.</li><li>Under <strong>Pages</strong>, type a <strong>Page range</strong> if you don&#39;t want every page.</li><li>Under <strong>Layout</strong>, choose <strong>One per sheet</strong>, <strong>Several per sheet</strong> or <strong>Booklet</strong>, then the <strong>Paper</strong>, <strong>Orientation</strong> and <strong>Scale</strong>.</li><li>Check the preview on the left. Use the arrows or type a number to move between sheets. The line below it counts the pages, sheet sides and sheets of paper.</li><li>Click <strong>Print</strong>. When the job has gone to the printer, a line such as &quot;Sent 6 sheets to Office printer.&quot; appears under the button.</li></ol><p>To keep the arranged sheets as a file, click <strong>Save layout as PDF…</strong> instead.</p><h3 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h3><p><strong>Printer</strong></p><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Printer</strong></td><td>Every printer installed in Windows. The default printer is listed first, marked &quot;(default)&quot;.</td><td>The Windows default printer</td></tr><tr><td><strong>Copies</strong></td><td>1 to 999.</td><td>1</td></tr><tr><td><strong>Collate</strong></td><td>With several copies, prints each copy in full before starting the next. Available from 2 copies.</td><td>On</td></tr><tr><td><strong>Two-sided</strong></td><td><strong>One-sided</strong>, <strong>Flip on long edge</strong> or <strong>Flip on short edge</strong>. Shows <strong>Not supported</strong> when the printer can&#39;t print on both sides.</td><td>One-sided</td></tr><tr><td><strong>Colour</strong></td><td><strong>Colour</strong> or <strong>Greyscale</strong>. Fixed to greyscale for a printer that can&#39;t print colour.</td><td>Colour</td></tr></tbody></table><p><strong>Pages</strong></p><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Page range</strong></td><td>The pages to print, such as <code>1-3, 5, 8-</code>. You can also type <code>odd</code>, <code>even</code> or <code>all</code>.</td><td>All pages</td></tr><tr><td><strong>Reverse order</strong></td><td>Prints the last page first.</td><td>Off</td></tr></tbody></table><p><strong>Layout</strong></p><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>One per sheet</strong> / <strong>Several per sheet</strong> / <strong>Booklet</strong></td><td>How pages are arranged on the sheets. See <a href="#layouts">Layouts</a> below.</td><td>One per sheet</td></tr><tr><td><strong>Pages per sheet</strong></td><td>2, 4, 6, 9 or 16. Several per sheet only.</td><td>2</td></tr><tr><td><strong>Page borders</strong></td><td>Draws a thin grey border round each page. Several per sheet only.</td><td>Off</td></tr><tr><td><strong>Paper</strong></td><td><strong>Same as the document</strong>, A4, A3, A5, Letter, Legal or Tabloid.</td><td>Same as the document</td></tr><tr><td><strong>Orientation</strong></td><td><strong>Automatic</strong>, <strong>Portrait</strong> or <strong>Landscape</strong>. Several per sheet only.</td><td>Automatic</td></tr><tr><td><strong>Scale</strong></td><td><strong>Fit to printable area</strong>, <strong>Actual size</strong>, or <strong>Custom…</strong> with a <strong>Percent</strong> from 10 to 400.</td><td>Fit to printable area</td></tr></tbody></table><p><strong>Press marks</strong></p><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Crop marks</strong></td><td>Draws marks at the corners showing where to trim the paper. One per sheet only.</td><td>Off</td></tr><tr><td><strong>Bleed</strong></td><td>0 to 10 mm, in steps of 0.5 mm. How far the crop marks stay from the page edge, leaving room for artwork that runs past it. Shown when crop marks are on.</td><td>3 mm</td></tr></tbody></table><h3 id="layouts" tabindex="-1">Layouts <a class="header-anchor" href="#layouts" aria-label="Permalink to &quot;Layouts&quot;">​</a></h3><ul><li><strong>One per sheet</strong> prints each page on its own sheet. With <strong>Paper</strong> set to <strong>Same as the document</strong>, the pages are printed as they are.</li><li><strong>Several per sheet</strong> puts 2, 4, 6, 9 or 16 pages on each sheet in a grid, left to right and top to bottom, each scaled to fit its cell. With <strong>Orientation</strong> on <strong>Automatic</strong>, the sheet is turned whichever way wastes less paper; for example, two portrait pages go side by side on a landscape sheet.</li><li><strong>Booklet</strong> reorders the pages two to a sheet so the printed stack folds in the middle into a booklet. Blank pages are added at the end to make a multiple of four. With <strong>Same as the document</strong>, each sheet is two pages wide; with a paper size, the sheet is used landscape and folded in half. Choosing <strong>Booklet</strong> switches <strong>Two-sided</strong> to <strong>Flip on short edge</strong> when the printer can print on both sides. If it can&#39;t, print the first side, then feed the stack back in for the second.</li></ul><h3 id="good-to-know" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li>Pages are drawn straight to the printer as vectors rather than as pictures, so text stays sharp at any printer resolution.</li><li>Landscape pages are turned to fit portrait paper, and the other way round.</li><li>Pages print in the order you type them in <strong>Page range</strong>, so <code>5, 1-4</code> prints page 5 first.</li><li><strong>Paper</strong> asks the printer for the matching paper size. If the printer has no paper within 2 mm of that size, or you leave <strong>Same as the document</strong>, the printer uses its own paper setting.</li><li><strong>Save layout as PDF…</strong> saves the sheets as the preview shows them, suggesting <code>&lt;name&gt;_print.pdf</code> next to the original. Copies, two-sided, colour and scale are printer settings, so they don&#39;t affect the saved file.</li><li>When the printer writes a file instead of paper (Microsoft Print to PDF, or an XPS printer), <strong>Print</strong> first asks where to save that file.</li><li>A network printer that is off or slow to answer can take a while to report what it supports. It appears straight away marked &quot;(checking…)&quot;, with the message &quot;Asking this printer what it supports (two-sided, colour, paper)…&quot;, and its options fill in when the answer arrives.</li><li>If no printers are installed, the tool says &quot;No printers are installed.&quot; You can still use <strong>Save layout as PDF…</strong>.</li><li>Password-protected PDFs can&#39;t be opened here. Unlock a copy with <a href="/tilepress/docs/security">Protect PDF</a> first.</li><li>Each print is listed in <a href="/tilepress/docs/history">History</a> as &quot;Print&quot;, and each saved layout as &quot;Print to PDF&quot;.</li></ul>',21)])])}const u=e(n,[["render",a]]);export{c as __pageData,u as default};
